/**
 * `rune verify` — mechanical verification modes that do not trust a green suite:
 *
 *   --integrity   test-diff weakening (P0)
 *   --junk        tautological / vacuous tests and "matches but junk" smells (P1)
 *   --lints       run `.rune/lints/rules.json` (generated by --reflect)
 *   --reflect     ingest recurring review findings → rules + conventions + AGENTS/CLAUDE pointers, then lint
 *   --oracle      compare a candidate against a reference command, URL, or fixture corpus
 *
 * Modes may be combined (except --oracle, which is exclusive). Exit 0 when clean
 * or warnings-only; exit 2 when a high-severity finding would block a strict hook;
 * exit 1 for usage or runner errors.
 */

import { analyzeJunkGit, formatJunkReport } from '../lib/junk-match.js';
import { analyzeGit, formatReport, resolveOverride, verdictFromResult } from '../lib/test-integrity.js';
import { formatLintsReport, formatReflectReport, runLints, runReflect } from '../lib/verify-lints.js';
import { formatOracleReport, runOracle } from '../lib/verify-oracle.js';

const USAGE = `  Usage:
    rune verify --integrity [--staged|--base <ref>] [--json]
    rune verify --junk [--staged|--base <ref>] [--json]
    rune verify --lints [--staged|--base <ref>] [--json]
    rune verify --reflect [--findings <file>] [--json]
    rune verify --oracle <cmd|url|fixtures-dir> [--candidate <cmd|url>] [--corpus <dir>] [--baseline <file>] [--json]
`;

export function parseVerifyArgs(args = {}) {
  const integrity = Boolean(args.integrity);
  const junk = Boolean(args.junk);
  const lints = Boolean(args.lints);
  const reflect = Boolean(args.reflect);
  const staged = Boolean(args.staged);
  const json = Boolean(args.json);
  const base = typeof args.base === 'string' && args.base ? args.base : undefined;
  const oracle = typeof args.oracle === 'string' && args.oracle ? args.oracle : args.oracle === true ? '' : undefined;
  const candidate = typeof args.candidate === 'string' && args.candidate ? args.candidate : undefined;
  const corpus = typeof args.corpus === 'string' && args.corpus ? args.corpus : undefined;
  const baseline = typeof args.baseline === 'string' && args.baseline ? args.baseline : undefined;
  const findings = typeof args.findings === 'string' && args.findings ? args.findings : undefined;
  const oracleMode = args.oracle != null && args.oracle !== false;
  return {
    integrity,
    junk,
    lints,
    reflect,
    staged,
    json,
    base,
    oracle,
    candidate,
    corpus,
    baseline,
    findings,
    oracleMode,
  };
}

function writeIo(io, stream, text) {
  const s = io[stream] || process[stream];
  s.write(text);
}

/**
 * @returns {Promise<number>} exit code
 */
export async function runVerify(projectRoot, args, io = {}) {
  const parsed = parseVerifyArgs(args);
  const { integrity, junk, lints, reflect, staged, json, base, oracleMode } = parsed;

  if (staged && base) {
    writeIo(io, 'stderr', '  rune verify: use either --staged or --base <ref>, not both.\n');
    return 1;
  }

  const modes = [integrity, junk, lints, reflect, oracleMode].filter(Boolean);
  if (modes.length === 0) {
    writeIo(io, 'stderr', '  rune verify: pass --integrity, --junk, --lints, --reflect, or --oracle <cmd|url>.\n');
    writeIo(io, 'stderr', USAGE);
    return 1;
  }
  if (oracleMode && modes.length > 1) {
    writeIo(io, 'stderr', '  rune verify: --oracle cannot be combined with other modes.\n');
    return 1;
  }

  if (oracleMode) {
    if (!parsed.oracle) {
      writeIo(io, 'stderr', '  rune verify: --oracle requires a command, URL, or fixture directory.\n');
      return 1;
    }
    try {
      const result = await runOracle(projectRoot, {
        oracle: parsed.oracle,
        candidate: parsed.candidate,
        corpus: parsed.corpus,
        baseline: parsed.baseline,
      });
      writeIo(io, 'stdout', formatOracleReport(result, { json }));
      return result.exitCode;
    } catch (err) {
      writeIo(io, 'stderr', `  rune verify --oracle: ${err.message}\n`);
      return 1;
    }
  }

  let exitCode = 0;

  if (integrity) {
    let result;
    try {
      result = analyzeGit(projectRoot, { staged, base });
    } catch (err) {
      writeIo(io, 'stderr', `  rune verify: failed to collect git diff (${err.message})\n`);
      return 1;
    }
    const override = resolveOverride({ env: io.env || process.env, cwd: projectRoot });
    const verdict = verdictFromResult(result, { override });
    writeIo(io, 'stdout', formatReport(result, { json }));
    if (override && result.blocked) {
      writeIo(io, 'stderr', `  test-integrity: override accepted from ${override.source}: ${override.reason}\n`);
    }
    exitCode = Math.max(exitCode, verdict.exitCode);
  }

  if (junk) {
    let result;
    try {
      result = analyzeJunkGit(projectRoot, { staged, base });
    } catch (err) {
      writeIo(io, 'stderr', `  rune verify --junk: failed to collect git diff (${err.message})\n`);
      return 1;
    }
    writeIo(io, 'stdout', formatJunkReport(result, { json }));
    if (result.blocked) exitCode = Math.max(exitCode, 2);
  }

  if (reflect) {
    try {
      const result = runReflect(projectRoot, { findingsPath: parsed.findings, staged, base });
      writeIo(io, 'stdout', formatReflectReport(result, { json }));
      if (result.blocked) exitCode = Math.max(exitCode, 2);
    } catch (err) {
      writeIo(io, 'stderr', `  rune verify --reflect: ${err.message}\n`);
      return 1;
    }
  } else if (lints) {
    try {
      const result = runLints(projectRoot, { staged, base });
      writeIo(io, 'stdout', formatLintsReport(result, { json }));
      if (result.blocked) exitCode = Math.max(exitCode, 2);
    } catch (err) {
      writeIo(io, 'stderr', `  rune verify --lints: ${err.message}\n`);
      return 1;
    }
  }

  return exitCode;
}
